"use strict";
const { subtotal } = require('./lines.cjs');
const { discounted } = require('./discount.cjs');
const { shipping } = require('./shipping.cjs');
function checkout(lines, percentOff = 0) {
  const beforeDiscount = subtotal(lines);
  return discounted(beforeDiscount, percentOff) + shipping(beforeDiscount);
}
module.exports = { checkout };

