"use strict";
function subtotal(lines) {
  return lines.reduce((sum, line) => sum + line.unitPriceCents * line.quantity, 0);
}
module.exports = { subtotal };

files.src/discount.cjs:
"use strict";
function discounted(cents, percentOff) {
  return Math.round(cents * (100 - percentOff) / 100);
}
module.exports = { discounted };

files.src/shipping.cjs:
"use strict";
function shipping(merchandiseCents) {
  return merchandiseCents > 5000 ? 0 : 500;
}
module.exports = { shipping };

